<div class="interactive-wrapper"><div class="card shadow-sm border-0 mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#eef2ff"><i class="fas fa-mug-hot text-primary"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Coffee Brew Optimizer</h5><p class="text-muted small mb-0">Optimize brew ratio, extraction yield, and grind size</p></div></div><button class="btn btn-sm rounded-pill px-3" id="btn-reset" style="background:#f1f5f9;font-weight:600"><i class="fas fa-undo me-1"></i>Reset</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="row g-3"><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Coffee (g)</label><input type="number" id="in-coffee" class="form-control form-control-lg" value="18" step="0.1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Water (g)</label><input type="number" id="in-water" class="form-control form-control-lg" value="300" step="1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Brew Method</label><select id="in-method" class="form-select form-select-lg"><option value="pourover">Pour Over</option><option value="french">French Press</option><option value="espresso">Espresso</option><option value="aeropress">AeroPress</option></select></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Grind Size</label><select id="in-grind" class="form-select form-select-lg"><option value="fine">Fine</option><option value="medium" selected>Medium</option><option value="coarse">Coarse</option></select></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Water Temp (°C)</label><input type="number" id="in-temp" class="form-control form-control-lg" value="96" step="1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">TDS % (optional)</label><input type="number" id="in-tds" class="form-control form-control-lg" value="1.35" step="0.01"></div></div><div class="mt-4 text-center"><button class="btn btn-primary btn-lg rounded-pill px-5 shadow-sm" id="btn-calc" style="min-width:260px;max-width:100%"><i class="fas fa-calculator me-2"></i>Calculate</button></div><div class="mt-3 p-3 rounded-4 border" style="background:#f8fafc"><p class="mb-0 small text-muted"><i class="fas fa-info-circle text-primary me-2"></i><b>SCA Standard:</b> Ratio 1:15–1:18 | Extraction 18–22% | TDS 1.15–1.35%</p></div></div></div><div id="res" class="card shadow-sm border-0 d-none mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#ecfdf5"><i class="fas fa-check-circle text-success"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Result</h5></div></div><button class="btn btn-success btn-sm rounded-pill px-4 shadow-sm" id="btn-copy"><i class="fas fa-copy me-1"></i>Copy</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="p-4 rounded-4 bg-light border text-center mb-3"><div class="small fw-bold text-uppercase text-muted mb-1">RESULT</div><div class="display-4 fw-bold text-dark" id="out-main">—</div><div class="small text-muted fw-bold" id="out-unit"></div></div><div id="out-detail" class="row g-3 mb-3"></div><div class="p-4 rounded-4 bg-light border"><h6 class="fw-bold mb-2 small text-uppercase text-muted"><i class="fas fa-lightbulb text-warning me-2"></i>Insights</h6><div id="out-ins" class="small"></div></div></div></div></div><style>.form-control-lg,.form-select-lg{border:1.5px solid #e2e8f0;border-radius:12px;font-size:1.05rem;padding:.75rem 1rem}.form-control:focus,.form-select:focus{border-color:#4f46e5;box-shadow:0 0 0 4px rgba(79,70,229,.1)}</style><script>document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var coffee=parseFloat(document.getElementById("in-coffee").value)||1,water=parseFloat(document.getElementById("in-water").value)||1,method=document.getElementById("in-method").value,grind=document.getElementById("in-grind").value,temp=parseFloat(document.getElementById("in-temp").value)||96,tds=parseFloat(document.getElementById("in-tds").value)||1.35;var ratio=water/coffee;var brewedWater=water*0.94;var extraction=(brewedWater*tds/100)/coffee*100;var ideal={pourover:{r:"1:15-1:17",g:"Medium",t:"92-96"},french:{r:"1:15-1:17",g:"Coarse",t:"93-96"},espresso:{r:"1:1.5-1:2.5",g:"Fine",t:"90-94"},aeropress:{r:"1:12-1:16",g:"Medium-Fine",t:"85-96"}};var rec=ideal[method];document.getElementById("out-main").textContent="1:"+ratio.toFixed(1);document.getElementById("out-unit").textContent="Brew Ratio";document.getElementById("out-detail").innerHTML='<div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Ratio</div><div class="h5 fw-bold mb-0 text-primary">1:'+ratio.toFixed(1)+'</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Extraction</div><div class="h5 fw-bold mb-0 text-info">'+extraction.toFixed(1)+'%</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">TDS</div><div class="h5 fw-bold mb-0 text-success">'+tds+'%</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Temp</div><div class="h5 fw-bold mb-0 text-warning">'+temp+'°C</div></div></div>';var ins=["Brew ratio: <b>1:"+ratio.toFixed(1)+"</b> (ideal for "+method+": "+rec.r+")","Extraction yield: <b>"+extraction.toFixed(1)+"%</b> (SCA target: 18-22%)"];if(extraction<18)ins.push("⚠ Under-extracted — try finer grind or longer brew time");else if(extraction>22)ins.push("⚠ Over-extracted — try coarser grind or shorter time");ins.push("Recommended grind: <b>"+rec.g+"</b> | Temp: <b>"+rec.t+"°C</b>");document.getElementById("out-ins").innerHTML='<ul class="list-unstyled mb-0">'+ins.map(function(x){return'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+"</li>";}).join("")+"</ul>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-coffee").value=18;document.getElementById("in-water").value=300;document.getElementById("in-temp").value=96;document.getElementById("in-tds").value=1.35;document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText("Ratio: "+document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\"fas fa-copy me-1\"></i>Copy";},2e3);});});</script>